import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{ProfileState}from"chrome://resources/mojo/chromeos/ash/services/cellular_setup/public/mojom/esim_manager.mojom-webui.js";import{getESimManagerRemote}from"./mojo_interface_provider.js";export async function getPendingESimProfiles(euicc){const response=await euicc.getProfileList();return filterByProfileProperties(response.profiles,(properties=>properties.state===ProfileState.kPending))}export async function getNonPendingESimProfiles(euicc){const response=await euicc.getProfileList();return filterByProfileProperties(response.profiles,(properties=>properties.state!==ProfileState.kPending))}async function filterByProfileProperties(profiles,callback){const filteredProfiles=[];for(const profile of profiles){const response=await profile.getProperties();if(callback(response.properties)){filteredProfiles.push(profile)}}return filteredProfiles}export async function getNumESimProfiles(){const euicc=await getEuicc();if(!euicc){return 0}const response=await euicc.getProfileList();if(!response||!response.profiles){return 0}return response.profiles.length}export async function getEuicc(){const eSimManagerRemote=getESimManagerRemote();const response=await eSimManagerRemote.getAvailableEuiccs();if(!response||!response.euiccs){return null}if(response.euiccs.length===0){return null}if(response.euiccs.length===1){return response.euiccs[0]}const euiccIndex=loadTimeData.getBoolean("useSecondEuicc")?1:0;return response.euiccs[euiccIndex]}async function getESimProfileDetails(iccid){if(!iccid){return null}const euicc=await getEuicc();if(!euicc){console.error("No Euiccs found");return null}const esimProfilesRemotes=await euicc.getProfileList();for(const profileRemote of esimProfilesRemotes.profiles){const profilePropertiesResponse=await profileRemote.getProperties();if(!profilePropertiesResponse||!profilePropertiesResponse.properties){return null}const profileProperties=profilePropertiesResponse.properties;if(profileProperties.iccid===iccid){return{profileRemote:profileRemote,profileProperties:profileProperties}}}return null}export async function getESimProfile(iccid){const details=await getESimProfileDetails(iccid);if(!details){return null}return details.profileRemote}export async function getESimProfileProperties(iccid){const details=await getESimProfileDetails(iccid);if(!details){return null}return details.profileProperties}